const articleData={
  'train-smarter':{title:'Train smarter: the 4 pillars of lasting progress',date:'October 18, 2026',intro:'Progress does not come from making every workout harder. It comes from making your training more coherent.',heads:[['Start with a clear target','Pick one primary goal for the next eight to twelve weeks. Strength, body composition and endurance can overlap, but your program works best when one outcome leads the decision-making.'],['Build around repeatable movements','Choose a small set of patterns you can practice and progress: squat, hinge, push, pull, carry and locomotion. Consistency makes technique efficient and improvement measurable.'],['Respect recovery','Training is the signal; recovery is where adaptation happens. Protect sleep, eat enough protein and leave room between genuinely demanding sessions.']]},
  'recovery-guide':{title:'Recovery is training: your practical weekly guide',date:'October 11, 2026',intro:'The best recovery plan is not complicated. It is a handful of useful habits performed often enough to matter.',heads:[['Protect your sleep window','Aim for consistent sleep and wake times before chasing specialised supplements or gadgets. A calmer final hour can change the quality of the night.'],['Move on rest days','A walk, easy cycle or short mobility sequence increases circulation and often reduces stiffness without adding meaningful fatigue.'],['Eat for the work you do','Build meals around protein, colourful plants, useful carbohydrates and adequate hydration. Your nutrition should support the training, not compete with it.']]},
  'build-consistency':{title:'How to build consistency when motivation fades',date:'October 03, 2026',intro:'Motivation is useful, but unreliable. A good training system works even when the day feels ordinary.',heads:[['Lower the starting friction','Pack your bag in advance, choose a repeatable training time and know the first exercise before you arrive. Make beginning easier than negotiating.'],['Set a minimum standard','On difficult weeks, a focused thirty-minute session still counts. A sustainable floor protects the habit better than an unrealistic ideal.'],['Track attendance first','Before obsessing over every metric, track whether you showed up. Consistent attendance creates the repetitions that make every other result possible.']]}
};
export function ArticlePage({article}:{article:keyof typeof articleData}){const data=articleData[article];return <main id="main"><PageHero eyebrow={`${data.date} · Coaching`} title={<>{data.title}</>} copy={data.intro}/><article className="section"><div className="container article"><p className="intro">{data.intro}</p>{data.heads.map(([head,body])=><section key={head}><h2>{head}</h2><p>{body}</p></section>)}<h2>Make it yours</h2><p>The strongest program is the one you can understand, recover from and repeat. Start with the smallest useful change, give it time and adjust from evidence rather than emotion.</p><Link className="button buttonDark" href="/contact">Speak with a coach <ArrowRight weight="bold"/></Link></div></article></main>}

